mapper.body:
{
  "model": "anthropic/claude-sonnet-4-6",
  "models": ["anthropic/claude-sonnet-4-6", "{{env.OPENROUTER_FALLBACK_MODEL}}"],
  "route": "fallback",
  "provider": { "allow_fallbacks": true },
  "messages": [
    {
      "role": "system",
      "content": "You are a friendly automotive service advisor. Write a professional vehicle status update email body (3–5 sentences, no markdown, no subject line) tailored to the status type. For 'ready': warmly inform the customer their vehicle is ready for pickup, include the vehicle name, mention business hours if included, invite them to call with questions. For 'in_progress': reassure the customer their vehicle is actively being worked on, mention the vehicle, provide a positive and confident tone. For 'waiting_parts': apologise for the delay, explain parts are on order, give an honest and empathetic message, assure them they will be updated. Always address the customer by first name. End every message with a professional sign-off (no placeholder signatures)."
    },
    {
      "role": "user",
      "content": "Status: {{1.body.propertyValue}}. Customer first name: {{4.data.properties.firstname}}. Vehicle: {{2.data.properties.vehicle_year}} {{2.data.properties.vehicle_make}} {{2.data.properties.vehicle_model}}. Deal name: {{2.data.properties.dealname}}. Today's date: {{formatDate(now; 'MMMM D, YYYY'; 'America/New_York')}}."
    }
  ],
  "temperature": 0.5,
  "max_tokens": 350
}

{
  "properties": {
    "hs_timestamp": "{{now}}",
    "hs_note_body": "Vehicle status update email sent (Scenario AR).\nNew Status: {{1.body.propertyValue}}\nVehicle: {{2.data.properties.vehicle_year}} {{2.data.properties.vehicle_make}} {{2.data.properties.vehicle_model}}\nEmail sent to: {{4.data.properties.email}}\nSent at: {{formatDate(now; 'MMMM D, YYYY [at] h:mm A'; 'America/New_York')}} ET\nAI message generated by claude-sonnet-4-6 via OpenRouter."
  },
  "associations": [
    {
      "to": { "id": "{{1.body.objectId}}" },
      "types": [
        {
          "associationCategory": "HUBSPOT_DEFINED",
          "associationTypeId": 214
        }
      ]
    }
  ]
}
